import{_ as o,l as i,o as e,c as s,v as t,p as d,x as r,d as E,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"查询改写与 HyDE","description":"","frontmatter":{"title":"查询改写与 HyDE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/query-rewrite-hyde.md","filePath":"llm/query-rewrite-hyde.md","lastUpdated":1789023840000}'),p={name:"llm/query-rewrite-hyde.md"};function A(m,a,_,c,u,D){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="查询改写与-hyde" tabindex="-1">查询改写与 HyDE <a class="header-anchor" href="#查询改写与-hyde" aria-label="Permalink to &quot;查询改写与 HyDE&quot;">​</a></h1><div class="epigraph"><p>用户问的是口语短句，索引里是陈述性段落。先把查询写成「像文档的文本」，再嵌入，往往比调切分更有效。</p><footer>—— Gao 等 HyDE；查询扩展与多查询改写的工程传统</footer></div><p><a href="/llm/multimodal-embeddings">上一课</a>把跨模态检索写成可缓存的双塔余弦空间，与 VLM 早融合分工。嵌入单元把向量训好了；RAG 进阶从查询侧开始。缺口是查询–文档不对称：口语提问不含手册里的小节标题与术语。本课写改写与 HyDE，不重讲图文召回。后课多跳默认：单跳改写仍不够时，才拆子问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口语「那个超时怎么调」不含手册里的小节标题与术语。BM25 与稠密都会弱。改写：用生成器把问题变成关键词、同义问法或多查询，分别检索再融合（RRF）。风险是改写错误被放大：生成器编造的术语会把检索带跑。</p><p>Gao 等人的 HyDE 走更远：让模型先写一份<strong>假设答案文档</strong>，再对这篇假文档嵌入去检索真文档。思路是：假文档在语言上更靠近语料中的陈述段，几何上更近。假文档事实可以错，只要风格与主题对；错得太具体会检索到错误实体。</p><p><span class="marginnote">改写是额外模型调用，延迟与费用要进 SLO。能用规则（拼标题路径、拆引号内短语）解决的，不要上生成。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶梯：规则规范化 → 多查询改写 → HyDE。每步保留原查询一路，与改写路融合，避免单点失败。HyDE 应对假设文档做长度限制，并禁止它直接当读者上下文——读者只读检索到的真块。评测看端到端 QA，也看检索召回；只看生成流畅会掩盖带偏。</p>',9)),(e(),d(h,null,{default:r(()=>[n(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E9%97%AE%22%5D%20--%3E%20RW%5B%22%E6%94%B9%E5%86%99%20%2F%20%E5%A4%9A%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20U%20--%3E%20HY%5B%22%E5%81%87%E8%AE%BE%E6%96%87%E6%A1%A3%20HyDE%22%5D%0A%20%20U%20--%3E%20RAW%5B%22%E5%8E%9F%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20RW%20--%3E%20RET%5B%22%E6%A3%80%E7%B4%A2%22%5D%0A%20%20HY%20--%3E%20RET%0A%20%20RAW%20--%3E%20RET%0A%20%20RET%20--%3E%20F%5B%22%E8%9E%8D%E5%90%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>稠密检索要求查询向量落在文档流形上。短问句与长陈述的边缘分布不同，即使对比训过非对称双塔，口语仍常偏出。改写与 HyDE 是在测试时把查询推回文档流形。生成器的幻觉在此表现为<strong>检索偏置</strong>而不是最终答幻觉；最终幻觉由阅读器课处理。若生成器与语料域差得远，假文档会落在错误流形，HyDE 有害。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>法律与医疗上，错误实体的假设文档风险高，应降级为多查询而不是假答案。下一课多跳：一跳改写找不到需要组合的证据链。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>改写把口语推回文档流形；原查询必须保留一路。</li><li>HyDE 用假文档嵌入，假文档不当读者输入。</li><li>改写错误会放大检索偏置，域差大时关掉 HyDE。</li><li>出处：Gao 等 HyDE；多查询融合实践。</li></ul>',6))])}const T=o(p,[["render",A]]);export{f as __pageData,T as default};
